<?php
require_once __DIR__.'/../../includes/init.php'; require_role('admin'); require_once __DIR__.'/../../includes/layout.php'; $pdo=db(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');try{
 if($action==='add'){$name=trim((string)($_POST['nama_lengkap']??''));$username=trim((string)($_POST['username']??''));$role=(string)($_POST['role']??'petugas');$pass=(string)($_POST['password']??'');if($name===''||mb_strlen($name)>50)throw new InvalidArgumentException('Nama wajib diisi maksimal 50 karakter.');if(!preg_match('/^[A-Za-z0-9._-]{3,50}$/',$username))throw new InvalidArgumentException('Username 3–50 karakter; gunakan huruf, angka, titik, garis bawah, atau tanda hubung.');if(!in_array($role,['admin','petugas','owner'],true))throw new InvalidArgumentException('Role tidak valid.');if(strlen($pass)<10)throw new InvalidArgumentException('Password awal minimal 10 karakter.');$s=$pdo->prepare('INSERT INTO tb_user(nama_lengkap,username,password,role,status_aktif) VALUES(?,?,?,?,1)');$s->execute([$name,$username,password_hash($pass,PASSWORD_DEFAULT),$role]);log_activity('Menambahkan pengguna '.$username);flash('success','Pengguna berhasil ditambahkan.');redirect('admin/users/index.php');}
 if($action==='update'){$id=input_int('id_user');$name=trim((string)($_POST['nama_lengkap']??''));$username=trim((string)($_POST['username']??''));$role=(string)($_POST['role']??'petugas');$active=(int)($_POST['status_aktif']??0);if($name===''||mb_strlen($name)>50)throw new InvalidArgumentException('Nama wajib diisi maksimal 50 karakter.');if(!preg_match('/^[A-Za-z0-9._-]{3,50}$/',$username))throw new InvalidArgumentException('Format username tidak valid.');if(!in_array($role,['admin','petugas','owner'],true)||!in_array($active,[0,1],true))throw new InvalidArgumentException('Nilai role/status tidak valid.');if($id===current_user()['id']&&($role!=='admin'||$active!==1))throw new InvalidArgumentException('Anda tidak dapat menonaktifkan atau mengubah role akun sendiri.');$s=$pdo->prepare('UPDATE tb_user SET nama_lengkap=?,username=?,role=?,status_aktif=? WHERE id_user=?');$s->execute([$name,$username,$role,$active,$id]);log_activity('Mengubah pengguna ID '.$id);flash('success','Data pengguna diperbarui.');redirect('admin/users/index.php');}
 if($action==='reset'){$id=input_int('id_user');$pass=(string)($_POST['password_baru']??'');if(strlen($pass)<10)throw new InvalidArgumentException('Password baru minimal 10 karakter.');$s=$pdo->prepare('UPDATE tb_user SET password=? WHERE id_user=?');$s->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);log_activity('Reset password pengguna ID '.$id);flash('success','Password pengguna berhasil direset.');redirect('admin/users/index.php');}
 if($action==='toggle'){$id=input_int('id_user');if($id===current_user()['id'])throw new InvalidArgumentException('Anda tidak dapat menonaktifkan akun sendiri.');$s=$pdo->prepare('UPDATE tb_user SET status_aktif=1-status_aktif WHERE id_user=?');$s->execute([$id]);log_activity('Mengubah status aktif pengguna ID '.$id);flash('success','Status pengguna diperbarui.');redirect('admin/users/index.php');}
 throw new InvalidArgumentException('Aksi tidak dikenali.');
}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():(($e instanceof PDOException&&$e->getCode()==='23000')?'Username sudah digunakan.':'Operasi gagal diproses.');if(!($e instanceof InvalidArgumentException)&&!($e instanceof PDOException&&$e->getCode()==='23000'))error_log('[ParkirSTRD users] '.$e->getMessage());}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT id_user,nama_lengkap,username,role,status_aktif FROM tb_user WHERE id_user=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
$q=trim((string)($_GET['q']??''));$page=page_number();$limit=10;$where='';$params=[];if($q!==''){$where=' WHERE nama_lengkap LIKE ? OR username LIKE ? OR role LIKE ?';$params=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];}$cnt=$pdo->prepare('SELECT COUNT(*) FROM tb_user'.$where);$cnt->execute($params);$total=(int)$cnt->fetchColumn();$s=$pdo->prepare('SELECT id_user,nama_lengkap,username,role,status_aktif,created_at FROM tb_user'.$where.' ORDER BY id_user DESC LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$s->execute($params);$rows=$s->fetchAll();render_header('Manajemen Pengguna','users');?>
<div class="page-intro"><div><h2>Manajemen pengguna</h2><p>Kelola akun, status aktif, dan pembagian role sesuai kewenangan.</p></div></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?>
<section class="panel"><div class="panel-heading"><div><h2><?= $edit?'Edit pengguna':'Tambah pengguna' ?></h2><p>Password disimpan dengan password_hash, bukan teks biasa.</p></div></div><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'add' ?>"><?php if($edit): ?><input type="hidden" name="id_user" value="<?= (int)$edit['id_user'] ?>"><?php endif; ?><div class="field"><label>Nama lengkap</label><input name="nama_lengkap" required maxlength="50" value="<?= h($edit['nama_lengkap']??'') ?>"></div><div class="field"><label>Username</label><input name="username" required minlength="3" maxlength="50" pattern="[A-Za-z0-9._-]+" value="<?= h($edit['username']??'') ?>"><small>Huruf, angka, titik, _ atau -.</small></div><div class="field"><label>Role</label><select name="role" required><?php foreach(['admin'=>'Admin','petugas'=>'Petugas','owner'=>'Owner'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($edit['role']??'petugas')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></div><?php if($edit): ?><div class="field"><label>Status akun</label><select name="status_aktif"><option value="1" <?= (int)$edit['status_aktif']===1?'selected':'' ?>>Aktif</option><option value="0" <?= (int)$edit['status_aktif']===0?'selected':'' ?>>Tidak aktif</option></select></div><?php else: ?><div class="field"><label>Password awal</label><input type="password" name="password" required minlength="10" autocomplete="new-password"><small>Minimal 10 karakter.</small></div><?php endif; ?><div class="form-actions"><?php if($edit): ?><a class="btn btn-secondary" href="<?= h(url('admin/users/index.php')) ?>">Batal</a><?php endif; ?><button class="btn btn-primary"><?= $edit?'Simpan perubahan':'Tambah pengguna' ?></button></div></form></section>
<section class="panel"><div class="table-toolbar"><div><strong>Daftar pengguna</strong><div class="muted" style="margin-top:4px"><?= $total ?> akun ditemukan</div></div><form class="toolbar-right" method="get"><div class="search-box"><input name="q" value="<?= h($q) ?>" placeholder="Cari nama, username, role..."></div><button class="btn btn-secondary">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>Pengguna</th><th>Username</th><th>Role</th><th>Status</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="td-main"><?= h($r['nama_lengkap']) ?><?= (int)$r['id_user']===current_user()['id']?' <span class="muted">(Anda)</span>':'' ?></td><td><?= h($r['username']) ?></td><td><?= h(ucfirst($r['role'])) ?></td><td><?= (int)$r['status_aktif']===1?status_badge('aktif'):status_badge('tidak_aktif') ?></td><td><?= h(date('d/m/Y',strtotime($r['created_at']))) ?></td><td><div class="table-actions"><a class="btn btn-secondary btn-sm" href="<?= h(url('admin/users/index.php?edit='.(int)$r['id_user'])) ?>">Edit</a><form method="post" style="display:inline"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id_user" value="<?= (int)$r['id_user'] ?>"><button class="btn btn-sm <?= (int)$r['status_aktif']?'btn-danger':'btn-success' ?>" data-confirm="<?= (int)$r['status_aktif']?'Nonaktifkan':'Aktifkan' ?> akun ini?" <?= (int)$r['id_user']===current_user()['id']?'disabled':'' ?>><?= (int)$r['status_aktif']?'Nonaktifkan':'Aktifkan' ?></button></form><details><summary class="btn btn-secondary btn-sm">Reset PW</summary><form method="post" class="reset-inline"><?= csrf_field() ?><input type="hidden" name="action" value="reset"><input type="hidden" name="id_user" value="<?= (int)$r['id_user'] ?>"><input type="password" name="password_baru" minlength="10" required placeholder="Password baru"><button class="btn btn-primary btn-sm">Simpan</button></form></details></div></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6"><div class="empty-state"><strong>Tidak ada pengguna ditemukan</strong>Coba kata kunci lain.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span>Menampilkan <?= count($rows) ?> dari <?= $total ?> pengguna</span><?= pagination($total,$limit,$page,url('admin/users/index.php'.($q!==''?'?q='.rawurlencode($q):''))) ?></div></section><?php render_footer(); ?>